'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var Uint8Array = require( '@stdlib/array/uint8' );
var run = require( './helpers.js' );
var rank = require( './../lib/rank.js' );
var cases = require( './fixtures/rank.json' ).cases;


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.strictEqual( typeof rank, 'function' );
	t.end();
});
tape( 'dpbtf2: private selected-triangle reference order and signed-zero bits', function test( t ) {
	cases.forEach( function each( x ) {
		var unchanged;
		var allowed;
		var before;
		var output;
		var raw;
		var a;
		var i;
		a = new Float64Array( x.after_scale_whole_bits.map(run.decode) );
		raw = new Uint8Array( a.buffer );
		before = Array.prototype.slice.call( raw );
		rank( (x.uplo === 'U') ? 121 : 122, 3, 0, 3, a, x.sAB1, x.sAB2, x.oAB );
		output = x.logical_physical_indices.map( function cell( j ) {
			return run.bits( a[j] );
		});
		allowed = {};
		x.logical_physical_indices.forEach( function allow( j ) {
			allowed[j] = true;
		});
		unchanged = true;
		for ( i = 0; (i < raw.length); i += 1 ) {
			if ( (!allowed[(((i-((i%8))))/8)] && (raw[i] !== before[i])) ) {
				unchanged = false;
			}
		}
		t.deepEqual( output, x.reference.logical_output_bits, 'original outer zero skip and inner arithmetic order' );
		t.ok( unchanged, 'every byte outside selected rank footprint unchanged' );
	});
	t.end();
});
